using System;
using System.IO;
using System.Linq;
using Newtonsoft.Json.Linq;
using UnityEngine;

namespace DungeonContract.Editor
{
    public static class DcP21Checks
    {
        private static JObject parameters;
        private static JObject geometry;
        private static readonly System.Collections.Generic.List<string> passed=new System.Collections.Generic.List<string>();
        private static DcP1World World(string loadout="ranger",bool practice=true)=>new DcP1World(new JObject{["parameters"]=parameters,["p1_world"]=geometry,["practice"]=practice,["weapon_stage"]=true,["p2_stage"]=true,["config"]=new JObject{["lifecycle_stage"]="room_camera_projectile_stage"},["run_id"]="p21_model",["seed"]=20261015,["members"]=new JArray(new JObject{["player_id"]="1",["slot"]=0,["loadout_id"]=loadout})});
        private static JToken Own(DcP1World world)=>world.Snapshot()["players"][0];
        private static DcP1Input Intent(DcP1World world)=>new DcP1Input{WeaponID=world.ActiveWeapon("1"),WeaponRevision=world.WeaponRevision("1"),Aim=0};
        private static void Require(bool value,string name){if(!value)throw new InvalidOperationException("P2.1 "+name);}
        private static void Case(string name,Action check){check();passed.Add(name);}
        private static void Tick(DcP1World world,long time){world.Input("1",Intent(world));world.Tick(time);}
        private static bool Act(DcP1World world,string kind,long time=0){world.AdvanceTime(time);return world.Action("1",kind,Intent(world));}
        private static JObject Point(float x,float y)=>new JObject{["x"]=x,["y"]=y};
        private static void Place(DcP1World world,int room,Vector2 player,params Vector2[] targets)
        {
            var state=world.Capture();state["players"][0]["Room"]=room;state["players"][0]["Position"]=Point(player.x,player.y);state["covers"]=new JArray();state["traps"]=new JArray();var template=(JObject)World().Capture()["enemies"][0];var list=new JArray();
            for(var index=0;index<targets.Length;index++){var enemy=(JObject)template.DeepClone();enemy["ID"]="fixture_"+index;enemy["Room"]=room;enemy["Position"]=Point(targets[index].x,targets[index].y);enemy["Origin"]=enemy["Position"].DeepClone();enemy["Health"]=1000;enemy["Maximum"]=1000;enemy["AttackAt"]=long.MaxValue;list.Add(enemy);}state["enemies"]=list;world.Restore(state);Tick(world,0);
        }
        private static JObject Shot(string id,int room,bool enemy=false)=>new JObject{["ID"]=id,["Action"]=id,["Owner"]=enemy?"fixture_enemy":"1",["Room"]=room,["Position"]=Point(3,3),["Direction"]=Point(1,0),["Speed"]=10,["Damage"]=12,["Unbounded"]=true,["Enemy"]=enemy,["Hit"]=new JArray()};
        public static void Run()
        {
            parameters=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/parameters-v4-p2-1.json")));
            geometry=JObject.Parse(File.ReadAllText(Path.GetFullPath("../../docs/game-demo/config/world-v4-p2-1.json")));
            passed.Clear();
            Case("15 room geometry with seven connectors",()=>{Require(((JArray)geometry["rooms"]).Count==15,"room count");Require(((JArray)geometry["doors"]).Count==14,"door count");Require((string)geometry["rooms"][8]["kind"]=="corridor","connector kind");});
            Case("main rooms use requested dimensions",()=>{Require((int)geometry["rooms"][2]["width"]==34&&(int)geometry["rooms"][2]["height"]==20,"mechanism size");Require((int)geometry["rooms"][1]["width"]==30&&(int)geometry["rooms"][1]["height"]==18,"foyer size");});
            Case("connector has no encounter budget",()=>{var corridor=geometry["rooms"][8];Require(((JArray)corridor["cover_points"]).Count==0&&((JArray)corridor["trap_points"]).Count==0,"corridor objects");});
            Case("unbounded player projectile crosses old range",()=>{var world=World();world.Tick(0);var input=Intent(world);input.Attack=true;world.Input("1",input);world.Tick(33);var shot=((JArray)world.Snapshot()["projectiles"])[0];Require((bool)shot["unbounded"]&&shot["remaining_range"].Type==JTokenType.Null,"unbounded state");});
            Case("turret acquisition baseline is 12 tiles",()=>{var world=World("runesmith");world.Tick(0);Require((int)parameters["loadouts"][1]["primary"]["range_milli_tiles"]==12000,"turret range");});
            Case("follow camera source values are bounded",()=>{Require((int)geometry["camera"]["view_width_milli_tiles"]==24000&&(int)geometry["camera"]["view_height_milli_tiles"]==13500,"camera view");Require((int)geometry["camera"]["follow_deadzone_x_milli_tiles"]<=1000&&((int)geometry["camera"]["damping_ms"])<=200,"camera bounds");});
            Case("trap policy remains after clear",()=>{Require((bool)geometry["trap"]["remain_after_clear"]&&((int)geometry["trap"]["cooldown_ms"])>0,"trap lifecycle");});
            Case("flight exceeds previous ten tile limit",()=>{var world=World();Place(world,2,new Vector2(3,3));Require(Act(world,"attack_press"),"fire");for(var time=33;time<=660;time+=33)Tick(world,time);var shot=world.Snapshot()["projectiles"][0];Require((float)shot["x"]>13&&(bool)shot["unbounded"],"old range cutoff");});
            Case("all emitted flight families are unbounded",()=>{var world=World();Tick(world,0);Act(world,"ability_primary");Require(((JArray)world.Snapshot()["projectiles"]).Count==3&&((JArray)world.Snapshot()["projectiles"]).All(item=>(bool)item["unbounded"]),"volley range");var tower=World("runesmith");Place(tower,2,new Vector2(3,3),new Vector2(14,3));Act(tower,"ability_primary");Tick(tower,33);Require(((JArray)tower.Snapshot()["projectiles"]).Any(item=>(bool)item["unbounded"]),"turret flight");});
            Case("rune reflects at open door source boundary once",()=>{var world=World("runesmith");Place(world,0,new Vector2(18,6));Act(world,"attack_press");for(var time=33;time<200;time+=33)Tick(world,time);var shot=world.Capture()["projectiles"][0];Require((int)shot["Room"]==0&&(int)shot["Bounces"]==0&&(float)shot["Direction"]["x"]<0,"door reflection");});
            Case("ordinary projectile does not cross open door",()=>{var world=World();Place(world,0,new Vector2(18,6));Act(world,"attack_press");for(var time=33;time<200;time+=33)Tick(world,time);Require(((JArray)world.Snapshot()["projectiles"]).Count==0,"cross room shot");});
            Case("late projectile damage survives owner down",()=>{var world=World();Place(world,2,new Vector2(3,3),new Vector2(15,3));Act(world,"attack_press");var state=world.Capture();state["players"][0]["Health"]=0;state["players"][0]["Life"]="downed";world.Restore(state);for(var time=33;time<800;time+=33)Tick(world,time);Require((long)Own(world)["damage"]==12,"downed attribution");Require(!Act(world,"ability_primary",800),"dead new cast");});
            Case("turret survives owner down and fires at eleven tiles",()=>{var world=World("runesmith");Place(world,2,new Vector2(3,3),new Vector2(14,3));Act(world,"ability_primary");var state=world.Capture();state["players"][0]["Health"]=0;world.Restore(state);Tick(world,33);Require(((JArray)world.Snapshot()["turrets"]).Count==1&&((JArray)world.Snapshot()["projectiles"]).Count==1,"turret owner alive gate");});
            Case("cutover retains original room projectile",()=>{var world=World();Place(world,2,new Vector2(3,3));Act(world,"attack_press");var state=world.Capture();state["players"][0]["Room"]=10;state["players"][0]["Position"]=Point(3,3);world.Restore(state);Tick(world,33);Require((int)world.Snapshot()["projectiles"][0]["room_id"]==2,"changed projectile room");});
            Case("permanent exit clears owned bullets and turret",()=>{var world=World("runesmith");Place(world,2,new Vector2(3,3),new Vector2(14,3));Act(world,"ability_primary");Tick(world,33);world.Leave("1");Require(((JArray)world.Snapshot()["projectiles"]).Count==0&&((JArray)world.Snapshot()["turrets"]).Count==0,"leave cleanup");});
            Case("budget rejects volley without cooldown or dash",()=>{var world=World();Place(world,2,new Vector2(3,3));var state=world.Capture();state["projectiles"]=new JArray(Enumerable.Range(0,127).Select(index=>Shot("full_"+index,2)));world.Restore(state);Require(!Act(world,"ability_primary")&&world.LastActionReason=="budget"&&(long)Own(world)["ability_remaining_ms"]==0&&(long)Own(world)["dodge_duration_remaining_ms"]==0,"atomic volley");Require(((JArray)world.Snapshot()["projectiles"]).Count==127,"evicted old shot");});
            Case("committed enemy reservation rejects new player fire",()=>{var world=World();Place(world,2,new Vector2(3,3),new Vector2(5,3));var state=world.Capture();state["enemies"][0]["ReservedShots"]=1;state["projectiles"]=new JArray(Enumerable.Range(0,127).Select(index=>Shot("full_"+index,2)));world.Restore(state);Require(!Act(world,"attack_press")&&(int)Own(world)["magazine"]==8&&(int)world.Snapshot()["projectile_load"]==128,"reserved capacity stolen");});
            Case("technical wait clears flight but retains turret without catchup",()=>{var world=World("runesmith");Place(world,2,new Vector2(3,3),new Vector2(14,3));Act(world,"ability_primary");Tick(world,33);world.TechnicalWait(true,33);Require(((JArray)world.Snapshot()["projectiles"]).Count==0&&((JArray)world.Snapshot()["turrets"]).Count==1,"wait cleanup");world.TechnicalWait(false,2033);Tick(world,2066);Require(((JArray)world.Snapshot()["projectiles"]).Count==0,"catchup fire");Tick(world,2700);Require(((JArray)world.Snapshot()["projectiles"]).Count>0,"normal resumed shot");});
            Case("technical wait consumes remaining turret lifetime",()=>{var world=World("runesmith");Tick(world,0);Act(world,"ability_primary");world.TechnicalWait(true,0);world.TechnicalWait(false,9000);Require(((JArray)world.Snapshot()["turrets"]).Count==0,"wait lifetime frozen");});
Case("spawn warning reserves budget and blocks early clear",()=>{var world=World("ranger",false);Place(world,1,new Vector2(3,3));var state=world.Capture();state["rooms"][1]["Status"]="active";state["rooms"][1]["Wave"]=3;state["rooms"][1]["Pending"]=new JArray("guard");world.Restore(state);Tick(world,33);Require(((JArray)world.Snapshot()["spawn_reservations"]).Count==1&&((JArray)world.Snapshot()["enemies"]).Count==0&&(string)world.Snapshot()["rooms"][1]["status"]=="active","birth cutpoint");for(var time=66;time<800;time+=33)Tick(world,time);Require(((JArray)world.Snapshot()["enemies"]).Count==0,"early birth");Tick(world,850);Require(((JArray)world.Snapshot()["enemies"]).Count==1,"missing entity");});
            Case("occupied birth point receives a new full warning",()=>{var world=World("ranger",false);Place(world,1,new Vector2(3,3));var state=world.Capture();state["rooms"][1]["Status"]="active";state["rooms"][1]["Wave"]=2;state["rooms"][1]["Pending"]=new JArray("guard");world.Restore(state);Tick(world,33);var birth=world.Snapshot()["spawn_reservations"][0];state=world.Capture();state["players"][0]["Position"]=Point((float)birth["x"],(float)birth["y"]);world.Restore(state);Tick(world,66);var next=world.Snapshot()["spawn_reservations"][0];Require((string)next["id"]!=(string)birth["id"]&&(long)next["remaining_ms"]==800,"silent relocation");});
            Case("combat room cannot exit through connector",()=>{var world=World("ranger",false);Place(world,1,new Vector2(28.6f,9),new Vector2(15,9));var state=world.Capture();state["rooms"][1]["Status"]="active";world.Restore(state);var input=Intent(world);input.Move=Vector2.right;world.Input("1",input);world.Tick(33);Require((int)Own(world)["room_id"]==1,"lock bypass");});
            Case("cleared room enters walkable connector automatically",()=>{var world=World("ranger",false);Place(world,1,new Vector2(28.6f,9));var state=world.Capture();state["rooms"][1]["Status"]="cleared";world.Restore(state);var input=Intent(world);input.Move=Vector2.right;world.Input("1",input);world.Tick(33);Require((int)Own(world)["room_id"]==9,"door traversal");});
            Case("completed room clears all flight and deployments",()=>{var world=World("runesmith",false);Place(world,1,new Vector2(3,3));Act(world,"ability_primary");var state=world.Capture();state["rooms"][1]["Status"]="active";state["rooms"][1]["Wave"]=3;state["projectiles"]=new JArray(Shot("remaining",1));world.Restore(state);Tick(world,33);Require((string)world.Snapshot()["rooms"][1]["status"]=="cleared"&&((JArray)world.Snapshot()["projectiles"]).Count==0&&((JArray)world.Snapshot()["turrets"]).Count==0,"clear cleanup");});
            Case("mechanism incomplete prevents cleanup and opening",()=>{var world=World("ranger",false);Place(world,2,new Vector2(3,3));var state=world.Capture();state["rooms"][2]["Status"]="active";state["rooms"][2]["Wave"]=2;state["projectiles"]=new JArray(Shot("remaining",2));world.Restore(state);Tick(world,33);Require((string)world.Snapshot()["rooms"][2]["status"]=="active"&&((JArray)world.Snapshot()["projectiles"]).Count==1,"premature clear");});
            Case("cleared room trap still hurts without reopening",()=>{var world=World("ranger",false);var state=world.Capture();state["players"][0]["Room"]=2;state["players"][0]["Position"]=Point(13,10);state["rooms"][2]["Status"]="cleared";state["rooms"][2]["Mechanism"]=true;state["enemies"]=new JArray();world.Restore(state);for(var time=33;time<=700;time+=33)Tick(world,time);Require((int)Own(world)["health"]==88&&(string)world.Snapshot()["rooms"][2]["status"]=="cleared","clear trap stopped");});
            Case("camera small room center and large room clamp",()=>{var center=DcP21Camera.Center((JObject)geometry["rooms"][0],new Vector2(3,3));Require(center==new Vector2(10,6),"small room zoom");var edge=DcP21Camera.Center((JObject)geometry["rooms"][2],new Vector2(33,19));Require(edge==new Vector2(22,13.25f),"room clamp");});
            Case("normal wipe never waits for surviving projectiles",()=>{var world=World("ranger",false);Place(world,1,new Vector2(3,3));Act(world,"attack_press");var state=world.Capture();state["players"][0]["Health"]=0;world.Restore(state);Tick(world,33);Require(world.Terminal&&world.Outcome=="failed"&&((JArray)world.Snapshot()["projectiles"]).Count==0,"turret postwipe wait");});
            Case("checkpoint preserves spawn reservations and projectile bounce",()=>{var world=World("runesmith");Place(world,2,new Vector2(3,3));Act(world,"attack_press");var before=world.Capture();var restored=World("runesmith");restored.Restore(before);Require(JToken.DeepEquals(before,restored.Capture()),"restore changes state");});
            Case("ordinary enemy body never blocks normal movement",()=>{var world=World();Place(world,2,new Vector2(3,3),new Vector2(3.4f,3));var input=Intent(world);input.Move=Vector2.right;world.Input("1",input);world.Tick(33);Require((float)Own(world)["x"]>3.1f,"normal body blocking");});
            Case("elite still blocks normal movement",()=>{var world=World();Place(world,2,new Vector2(3,3),new Vector2(3.8f,3));var state=world.Capture();state["enemies"][0]["Kind"]="elite";world.Restore(state);var input=Intent(world);input.Move=Vector2.right;world.Input("1",input);world.Tick(33);Require((float)Own(world)["x"]==3,"elite body pass");});
            Case("committed attack cannot retarget during last two hundred ms",()=>{var world=World("ranger",false);Place(world,2,new Vector2(6,3),new Vector2(5,3));var state=world.Capture();state["enemies"][0]["Kind"]="archer";state["enemies"][0]["AttackAt"]=0;state["rooms"][2]["Status"]="active";state["rooms"][2]["Wave"]=3;state["enemies"][0]["ReadyAt"]=0;world.Restore(state);Tick(world,33);var until=(long)world.Capture()["enemies"][0]["WarningUntil"];Tick(world,until-190);var before=world.Capture()["enemies"][0]["Aim"].DeepClone();state=world.Capture();state["players"][0]["Position"]=Point(5,8);world.Restore(state);Tick(world,until-30);Require(JToken.DeepEquals(before,world.Capture()["enemies"][0]["Aim"]),"late aim tracking");});
            Case("archer beyond eight tiles delays warning and follows",()=>{var world=World("ranger",false);Place(world,2,new Vector2(3,3),new Vector2(20,3));var state=world.Capture();state["enemies"][0]["Kind"]="archer";state["enemies"][0]["AttackAt"]=0;state["enemies"][0]["ReadyAt"]=0;world.Restore(state);Tick(world,33);Require(string.IsNullOrEmpty((string)world.Snapshot()["enemies"][0]["warning"])&&(float)world.Snapshot()["enemies"][0]["x"]<20,"unlimited acquisition");});
            Case("foreign room dynamic and precise effect data are cropped",()=>{var world=World();Place(world,2,new Vector2(3,3),new Vector2(10,3));var state=world.Capture();state["enemies"][0]["Room"]=1;state["effects"]=new JArray(new JObject{["id"]="foreign_hit",["kind"]="hit",["actor"]="1",["target"]="hidden_enemy",["room"]=1,["x"]=10,["y"]=3,["amount"]=12,["at"]=0});world.Restore(state);var visible=DcP21Interest.ForPlayer(world.Snapshot(),"1");Require(((JArray)visible["enemies"]).Count==0&&(float)visible["effects"][0]["x"]==0&&visible["effects"][0]["target"].Type==JTokenType.Null,"foreign precision disclosure");});
            Case("pending spawn queue survives checkpoint restoration",()=>{var world=World();var state=world.Capture();state["rooms"][2]["Pending"]=new JArray("guard","archer","charger");world.Restore(state);Require(((JArray)world.Capture()["rooms"][2]["Pending"]).Count==3,"lost finite pending queue");});
            Case("invalid projectile state aborts rather than lingering forever",()=>{var world=World();Place(world,2,new Vector2(3,3));var state=world.Capture();var invalid=Shot("invalid",2);invalid["Speed"]=0;state["projectiles"]=new JArray(invalid);world.Restore(state);Tick(world,33);Require(world.Terminal&&world.Outcome=="aborted","zero speed lifetime");});
            File.WriteAllText((DcBootstrap.DemoEvidenceRoot+"/")+(DcV6Profile.Active?"v6-regression-":"")+"p21-model-checks.json",new JObject{["kind"]="authoritative_p2_1_graybox_model",["passed"]=passed.Count,["cases"]=new JArray(passed),["runtime"]="NOT_RUN",["human"] = false}.ToString());Debug.Log("DC P2.1 checks passed: "+passed.Count);
        }
    }
}
